const sourceUrl = (item.url || '').startsWith('http') ? item.url : 'https://vietstock.vn' + item.url;

return {
  json: {
    ...item,
    videoId: `${dateStr}-${slug}-${rand}`,
    channelName: 'Tui đầu tư',
    sourceUrl
  }
};

const BACKSLASH = String.fromCharCode(92);
const NEWLINE = String.fromCharCode(10);
const CARRIAGE_RETURN = String.fromCharCode(13);

function repairJsonQuotes(text) {
  let result = '';
  let inString = false;
  let escapeNext = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (!inString) {
      result += ch;
      if (ch === '"') inString = true;
      continue;
    }
    if (escapeNext) {
      result += ch;
      escapeNext = false;
      continue;
    }
    if (ch === BACKSLASH) {
      result += ch;
      escapeNext = true;
      continue;
    }
    if (ch === '"') {
      let j = i + 1;
      while (j < text.length && /\s/.test(text[j])) j++;
      const next = text[j];
      if (next === undefined || next === ',' || next === '}' || next === ']' || next === ':') {
        result += ch;
        inString = false;
      } else {
        result += BACKSLASH + '"';
      }
      continue;
    }
    if (ch === NEWLINE) {
      result += BACKSLASH + 'n';
      continue;
    }
    if (ch === CARRIAGE_RETURN) {
      continue;
    }
    result += ch;
  }
  return result;
}

function safeJsonParse(text, sourceName) {
  try {
    return JSON.parse(text);
  } catch (e1) {
    try {
      return JSON.parse(repairJsonQuotes(text));
    } catch (e2) {
      throw new Error(`${sourceName} output không phải JSON hợp lệ (đã thử tự sửa nhưng vẫn lỗi): ${e2.message}`);
    }
  }
}

