const BASE_DIR = '/Users/YOUR_USERNAME/tui-dau-tu-videos';
const SUBSCRIBE_CLIP = `${BASE_DIR}/assets/subscribe-tui-dau-tu_final.mp4`;

const W = 832;
const H = 1216;
const FPS = 30;

const staticData = $getWorkflowStaticData('global');
const scenes = (staticData.scenes || []).slice().sort((a, b) => a.sceneId - b.sceneId);
if (scenes.length === 0) {
  throw new Error('Không có scene nào trong staticData.scenes để render video.');
}

const videoId = $('Generate Video ID').first().json.videoId;
const dir = `${BASE_DIR}/${videoId}`;
const finalVideoPath = `${dir}/final_video.mp4`;
const scriptPath = `${dir}/render.sh`;

function kenBurnsFilter(camera, duration) {
  const frames = Math.max(1, Math.round(duration * FPS));
  const zoomStep = 0.0015;
  if (camera === 'slow-zoom' || camera === 'push-in') {
    return `zoompan=z='min(zoom+${zoomStep},1.2)':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':d=${frames}:s=${W}x${H}:fps=${FPS}`;
  }
  if (camera === 'pull-out') {
    return `zoompan=z='if(eq(on,0),1.2,max(zoom-${zoomStep},1.0))':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':d=${frames}:s=${W}x${H}:fps=${FPS}`;
  }
  if (camera === 'pan-left') {
    return `zoompan=z='1.15':x='if(eq(on,0),iw-iw/zoom,x-2)':y='ih/2-(ih/zoom/2)':d=${frames}:s=${W}x${H}:fps=${FPS}`;
  }
  if (camera === 'pan-right') {
    return `zoompan=z='1.15':x='if(eq(on,0),0,x+2)':y='ih/2-(ih/zoom/2)':d=${frames}:s=${W}x${H}:fps=${FPS}`;
  }
  if (camera === 'parallax') {
    return `zoompan=z='min(zoom+${zoomStep},1.25)':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':d=${frames}:s=${W}x${H}:fps=${FPS}`;
  }
  return `scale=${W}:${H}`;
}

const lines = [];
lines.push('#!/bin/bash');
lines.push('set -e');
lines.push(`mkdir -p '${dir}'`);

const sceneOutputs = [];
scenes.forEach((scene) => {
  const outPath = `${dir}/scene_${scene.sceneId}_render.mp4`;
  sceneOutputs.push(outPath);
  const duration = scene.duration || 5;
  const filter = kenBurnsFilter(scene.camera, duration);
  const cmd = `ffmpeg -y -loop 1 -i '${scene.imagePath}' -i '${scene.audioPath}' -filter_complex "[0:v]scale=${W * 2}:${H * 2},${filter},format=yuv420p[v]" -map "[v]" -map 1:a -c:v libx264 -pix_fmt yuv420p -c:a aac -b:a 192k -shortest -t ${duration} '${outPath}'`;
  lines.push(cmd);
});

const allClips = [...sceneOutputs, SUBSCRIBE_CLIP];
const inputArgs = allClips.map((p) => `-i '${p}'`).join(' ');
const filterParts = allClips.map((_, i) => `[${i}:v]scale=${W}:${H}:force_original_aspect_ratio=decrease,pad=${W}:${H}:(ow-iw)/2:(oh-ih)/2,setsar=1,fps=${FPS},format=yuv420p[v${i}];[${i}:a]aformat=sample_rates=44100:channel_layouts=stereo[a${i}]`).join(';');
const concatInputs = allClips.map((_, i) => `[v${i}][a${i}]`).join('');
const concatFilter = `${filterParts};${concatInputs}concat=n=${allClips.length}:v=1:a=1[outv][outa]`;

lines.push(`ffmpeg -y ${inputArgs} -filter_complex "${concatFilter}" -map "[outv]" -map "[outa]" -c:v libx264 -pix_fmt yuv420p -c:a aac -b:a 192k '${finalVideoPath}'`);

const scriptContent = lines.join('\n') + '\n';

return [{
  json: { videoId, dir, scriptPath, finalVideoPath },
  binary: {
    script: await this.helpers.prepareBinaryData(Buffer.from(scriptContent, 'utf-8'), 'render.sh', 'text/x-shellscript')
  }
}];

